"""Serialize this model's authored stakeholder questions and acceptance design."""
import json
import re
from pathlib import Path
RUN=Path(__file__).resolve().parent
def refs(*n): return [f'SRC-{i:03d}' for i in n]

def build():
    rows=[
      ('GRI 1 Foundation','Global Reporting Initiative','https://www.globalreporting.org/publications/documents/english/gri-1-foundation-2021/','2021; exact amendment pin pending','standard','Selected section 2.4 and impact discussion; source-qualified interests and affectedness, not all stakeholder theories.'),
      ('GRI 2 General Disclosures','Global Reporting Initiative','https://www.globalreporting.org/publications/documents/english/gri-2-general-disclosures-2021/','2021; Disclosure 2-29','standard','Selected stakeholder engagement requirements/guidance, barriers, representation and feedback; not executed reporting conformance.'),
      ('ESS10 Guidance Note for Borrowers','World Bank','https://thedocs.worldbank.org/en/doc/e90b65996fdb2dcfc71f0018d55692d5-0290012025/original/ESS10-Stakeholder-Engagement-and-Information-Disclosure-English.pdf','First Edition June 2018, not the URL upload year','first-party-doc','Cover/disclaimer and selected pages 7-9; guidance is non-mandatory and ESF/IPF-specific, not universal law.'),
      ('OECD Guidelines for Citizen Participation Processes, implementation chapter','OECD','https://www.oecd.org/en/publications/2022/09/oecd-guidelines-for-citizen-participation-processes_63b34541/full-report/component-6.html','2022','first-party-doc','Selected decision space, inclusion and feedback-loop sections; web research text readable, direct HTTP request failed.'),
      ('PROV-O: The PROV Ontology','W3C','https://www.w3.org/TR/prov-o/','Recommendation; dated release pin pending','ontology','Qualified activity/agent provenance for recording assertions; not stakeholder entitlement or a truth-ranking rule.'),
      ('Date and Time on the Internet: Timestamps','IETF','https://www.rfc-editor.org/rfc/rfc3339','RFC 3339 July 2002','standard','Selected timestamp grammar and examples; precise instants separate from uncertain date-only effect.'),
    ]
    sources=[dict(id=f'SRC-{i:03d}',title=t,organization=o,url=u,version_or_date=v,source_type=k,primary_source=True,authority_tier=1 if k!='first-party-doc' else 2,accessed_at='2026-09-09T20:48:00Z',relevance=r) for i,(t,o,u,v,k,r) in enumerate(rows,1)]
    ids=['stake-identity','stake-discovery','interest-attribution','impact-rights','stake-representation','participation-conditions','influence-assessment','engagement-purpose','feedback-response','stake-lifecycle','stake-stewardship','stake-exchange']
    sr=[refs(1,2,5),refs(1,3),refs(1,2,5),refs(1,3),refs(2,3),refs(2,3,4),refs(1,3,4),refs(2,4),refs(2,4,5),refs(1,5,6),refs(2,3,5),refs(1,2,3,4,5,6)]
    kinds=[['identity','relationship','composition'],['classification','constraint','quality'],['definition','provenance','exception'],['relationship','measurement','authority'],['authority','constraint','exception'],['access','privacy','security'],['evidence','measurement','constraint'],['classification','decision','ownership'],['evidence','relationship','authority'],['temporal','lifecycle','state'],['ownership','access','retention'],['interoperability','validation','process']]
    n=0; bundles=[]
    for group in re.split(r'(?m)^## ',(RUN/'question-design.md').read_text(encoding='utf-8'))[1:]:
        title=re.sub(r'^\d+\s+','',group.split('\n',1)[0]); layers=[]
        for section in re.split(r'(?m)^### ',group)[1:]:
            heading,body=section.split('\n',1); name=re.sub(r'^\d+\.\d+\s+','',heading)
            qs,answertext=body.split('Answer groups:',1)
            questions=re.findall(r'(?m)^\d\. (.+\?)$',qs)
            groups=re.findall(r'([a-zA-Z]+)\{([^}]+)\}',answertext)
            assert len(questions)==len(groups)==3
            lid=ids[n]
            desc='Attributed scoped stake information for '+name.lower()+'. Do not infer sensitive traits, consent or legal authority from stakeholder status.'
            fields=[dict(id=lid+'-'+key.lower(),name=key,description='Proposed structured answer: '+fields+'. Preserve explicit unknowns and source-qualified assessments; nested executable schema remains deferred.',value_kind='object',cardinality='1',required=True,source_refs=sr[n]) for key,fields in groups]
            finding=dict(id=lid+'-record',name=name+' record',description=desc,source_refs=sr[n],questions=[dict(id=lid+f'-q{i+1:02d}',text=q,kind=kinds[n][i],answer_data=[fields[i]['id']]) for i,q in enumerate(questions)],data_elements=fields,artifacts=[dict(id=lid+'-artifact',name=name+' assertion artifact',description='Versioned '+name.lower()+' assertion with minimal authorized evidence references; no unnecessary private party or grievance payloads.',media_or_form=['text/markdown','application/json','application/yaml','external reference'],serial=True,identity_strategy='Master-qualified ID first, else Dimension UUID; immutable revision and digest separately. Timestamp alone is not unique identity.',source_refs=sr[n])],inline_only_rationale=None)
            layers.append(dict(id=lid,name=name,description=desc,source_refs=sr[n],findings=[finding])); n+=1
        assert len(layers)==2
        bundles.append(dict(id='stake-'+re.sub('[^a-z]+','-',title.lower()).strip('-'),name=title,description='Scoped stakeholder '+title.lower()+'.',rationale='Proposed pairing of two stake-owned records; does not replace party identity, rights adjudication or engagement workflow.',source_refs=sorted(set(x for layer in layers for x in layer['source_refs'])),layers=layers))
    assert n==12 and len(bundles)==6
    model=dict(registry_id='vr.wm-org-013',model_id='WM-ORG-013',name='Stakeholder / Interest',entry_kind='relationship',purpose='Describe who has an attributed stake in a subject, how they are affected, represented and heard, with safeguarded evidence.',scope_statement='One party or collective stake relationship to an organization, project, decision or impact. Interest, affectedness, influence, rights, representation and engagement assertions stay distinct. This is not a person profile or an instruction to influence people.',in_scope=['Scoped stakeholder identity and source-qualified identification','Attributed interests, impacts, representation and participation conditions','Engagement-response references, revision, confidential stewardship and mappings'],out_of_scope=['Party identity, equity ownership, political or personality profiling','Contacting stakeholders, persuading individuals or executing engagement/grievance workflows','Inferring consent, assigning legal rights or universally ranking people'],boundary_notes=[dict(neighbor=a,distinction=b,source_refs=c) for a,b,c in [('Organization and person/group masters','A stakeholder role exists relative to a subject; do not remaster the party.',refs(1,2)),('Ownership or influence','Stake does not mean shares, control or power; low influence does not remove affectedness.',refs(1,3)),('Representation and consent','Recorded mandate is scope-bound and contestable; attendance or silence does not establish consent.',refs(2,3,4)),('Engagement and grievance workflow','Reference events, responses and commitments without executing communications or disposing concerns.',refs(2,3,4))]])
    services=dict(
      dimension=dict(owner_package_requirements=['Declare stakeholder-data owner and steward.','Identify party, subject, impact, engagement and grievance masters.','Bind lawful purpose, confidentiality, delegation, conflict and retention policies.'],namespace_guidance='Relationship identifier is qualified by master and scope; do not use party name alone or collapse distinct stakes into one profile.',registry_links=['Stakeholder-interest registry','Party and subject registries','Evidence and engagement references','Model, policy and revision registries']),
      canon_and_patch=dict(canonicalization_rules=['Keep declared versus inferred interest and basis of representation explicit.','Rights, affectedness and influence are separate; preserve uncertainty and valid scope.'],patch_rules=['Extend under a namespaced version pinned to the base digest.','Append corrections with expected-head check; preserve justified evidence and contested positions.'],compatibility_rules=['Changes to interest, impact or rating meaning need migration and source-scope loss report.','Do not coerce absent, withheld or not-yet-heard into no interest or consent.']),
      artifact_rules=dict(identity_priority=['Authoritative master-system ID','Governed issuer-qualified URI','Dimension-issued UUID with namespace'],timestamp_rule='RFC 3339 with seconds and explicit offset or Z for precise observation/recording; preserve uncertain effective dates separately.',serial_naming_rule='Stake artifact-kind prefix, escaped stable identifier and revision; never expose sensitive party names in filenames.',integrity_rule='Verify exact-byte digest and authorized source revision; integrity is not proof of stakeholder consent or truth.'),
      policies=['Do not infer sensitive attributes, political affiliation or personality from an interest assertion.','Never rank rights by influence; require method, scale, uncertainty and review for proposed priority assessments.','No automatic outreach or disclosure from stakeholder registration.','Minimize private data, retain dissent and separate record authority from representation of people.'],
      crud=dict(read=['Read owner policy, subject scope, attribution, time, representation limits and assurance first.'],create=['Record an authorized minimal stake assertion with unknowns, not guessed group membership or consent.'],update=['Append revised interests/representation/evidence under expected-head and purpose checks; preserve separately attributed disagreement.'],delete=['Apply retention and legal-hold rules with authorized correction/tombstone; deleting a record cannot extinguish a right or grievance.']),
      roles=[dict(name=a,responsibilities=[b]) for a,b in [('Dimension owner','Defines purpose and delegated scope.'),('Stakeholder-data steward','Maintains scope, attribution and review obligations.'),('Contributor','Records authorized minimal expressed or observed evidence.'),('Reviewer','Checks representation disputes, gaps and bias in assessments.'),('Custodian','Enforces disclosure, retention and evidence-reference controls.')]],
      access=dict(default_rule='Deny unless owning Dimension grants purpose-specific access; stakeholder status is not permission.',scopes=['bundle','layer','finding','artifact'],exceptions=['Only explicit time-limited delegated access with necessary redaction; public role does not waive private concern protection.'],audit_requirements=['Record actor, purpose, authorized scope, version and disclosure decisions without confidential payloads or secrets.']),
      agents_bootstrap=dict(filename='AGENTS.md',required_fields=['Name','Type','Specification URL','Storage type URL','Interface URL','Processes URL'],read_order=['Dimension purpose and privacy/delegation policy','Pinned model, subject and party master references','Attribution, interests, impact, representation and time','Safe record operations, validation, extension and retirement']))
    fnrows=[
      ('identify-stake','Identify scoped stake','Resolve the party-subject relationship without creating an intrusive party profile.',['Authorized party and subject refs','Definition and evidence'],['Scoped candidate or explicit unknown'],['Purpose and access permission','Source-qualified identification rule'],['Read-only candidate; ambiguous identity stays unresolved'],refs(1,2,3)),
      ('record-interest','Record attributed interest','Append a stated or explicitly inferred interest with provenance.',['Interest assertion','Attribution mode','Evidence refs','Expected head'],['Immutable assertion or conflict'],['Contributor authority','No sensitive-trait inference','Required fields validated'],['Local append only; no outreach, consent inference or manipulation'],refs(1,2,5)),
      ('review-stakeholder-gaps','Review stakeholder coverage gaps','Identify known gaps in a scoped register without ranking individual worth.',['Authorized coverage boundaries','Impact references','Existing identification evidence'],['Coverage gaps and proposed review tasks'],['Read permission','Affectedness not replaced by influence score'],['Read-only review; no guessed protected membership or automatic exclusion'],refs(1,3,4)),
      ('link-response','Link engagement response','Connect authorized feedback to mastered response or decision records.',['Feedback ref','Response/commitment refs','Expected revision'],['Traceable link and unresolved response status'],['Write scope','Target masters verified','No agreement inferred from acknowledgement'],['Local link only; no message sending or commitment execution'],refs(2,4,5)),
      ('revise-stake','Revise relevance or representation','Append changes while retaining prior attributed positions.',['Prior revision','Changed scope or mandate evidence','Valid/recorded time'],['Successor revision or contested set'],['Expected-head check','Reviewer policy for contested mandate','Retention reviewed'],['Compensating revision for errors; no deletion of rights or grievance claims'],refs(2,3,5,6)),
      ('export-stake','Export minimized projection','Apply versioned mappings under explicit privacy limits.',['Authorized fields','Target profile','Loss and fixture definitions'],['Minimized projection or refusal'],['Disclosure authority','Mapping and reidentification risk reviewed'],['No public release without explicit authority; incomplete evidence yields loss warning/refusal'],refs(1,2,3,4)),
    ]
    functions=[dict(id=i,name=n,description=d,inputs=a,outputs=b,preconditions=c,effects=e,source_refs=s) for i,n,d,a,b,c,e,s in fnrows]
    composition=[dict(target=t,relation=r,purpose=p,required=req,source_refs=s) for t,r,p,req,s in [('WM-ORG-001','REFERENCE','Proposed organization reference when it is party or subject; other party/subject masters use typed references, not invented IDs.',False,refs(1,2)),('https://www.globalreporting.org/publications/documents/english/gri-2-general-disclosures-2021/','ALIGN','Candidate engagement-reporting alignment, not complete GRI conformance.',False,refs(2)),('https://www.w3.org/TR/prov-o/','ALIGN','Candidate provenance of interest assertion, not stakeholder entitlement.',False,refs(5))]]
    dims=[('identity','Scoped relationship and party/subject references.'),('classification','Affected, potentially affected or interested under declared definition.'),('direct properties','Attributed interest, scope, representation and time; ratings are assessments.'),('recognition','Evidence distinguishes expressed interest from analyst hypothesis.'),('capabilities','Six record-maintenance operations; no outreach or persuasion.'),('lifecycle','Relevance, engagement withdrawal and record retirement differ.'),('temporal','Valid interval and knowledge time preserve precision.'),('relationships','Party, subject, impact and engagement masters referenced.'),('provenance','Source and representative attribution retained.'),('ownership','Data steward is not the stakeholder or their rights owner.'),('access','Purpose and field-level confidentiality controls.'),('retention','Necessity, correction and justified evidence preservation.'),('interoperability','Source/profile distinctions and loss-aware projections.')]
    coverage=dict(claim='Bounded proposed stakeholder-interest context contract, not exhaustive engagement law, a personal profile or executed standards conformance.',confidence='medium',checklist=[dict(dimension=d,status='covered',notes=n) for d,n in dims]+[dict(dimension='validation',status='gap',notes='Question/answer traceability designed; executable nested schemas, privacy and negative fixtures not implemented.'),dict(dimension='Physical material and geometry',status='not-applicable',notes='Stake is relational, not a physical object; party properties remain delegated.')],known_omissions=['Claude and Grok each timed out once; no independent review, Codex-only reviewable-draft.','Selected source passages only; license, exact mutable release pins and full jurisdiction-specific applicability remain unverified.','OECD chapter readable through web research but direct HTTP failed; transport access limitation remains visible.','No executable nested schema, engagement adapter, representation verifier or privacy/round-trip fixtures delivered.','World Bank guidance is June 2018 first edition and non-mandatory; latest revisions and full boxed standards are not exhaustively reviewed.','Role/impact-specific profiles, approved composition ledger edges and independent review remain pending.'],conflicts=[],regional_assumptions=['GRI reporting, World Bank ESF/IPF and OECD public-governance guidance have different scopes; none is asserted as universal law or permission to contact individuals.'],adversarial_checks=['Low influence must not exclude severely affected groups.','Silence and attendance must not become consent.','Representative mandate can be contested and narrower than a group.','Inferred concern is not self-expression.','Engagement withdrawal does not end an underlying impact.','Scores require scale, date, method and uncertainty.','Public group names do not authorize sensitive-data inference.','Local updates do not change rights, grievances or commitments.'])
    return dict(schema_version='1.0.0',model=model,sources=sources,structure=dict(bundles=bundles),functions=functions,composition=composition,service_layers=services,coverage=coverage)

if __name__=='__main__':
    (RUN/'codex.result.json').write_text(json.dumps(build(),ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
